        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.spy_sma = self.SMA(self.spy, 100, Resolution.Daily)
        self.aapl_rsi = self.RSI(self.aapl, 14, MovingAverageType.Wilders, Resolution.Daily)

        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.SetWarmUp(100, Resolution.Daily)

    def OnData(self, data: Slice):
        if data.ContainsKey(self.spy):
            if self.spy_sma.IsReady:
                self.previous_spy_sma = self.spy_sma.Current.Value

        if data.ContainsKey(self.aapl):
            aapl_close = data[self.aapl].Close

            if self.previous_aapl_close is not None:
                if aapl_close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.previous_aapl_close = aapl_close

        if self.IsWarmingUp:
            return

        required_symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]
        if any(not data.ContainsKey(symbol) for symbol in required_symbols):
            return

        if not self.spy_sma.IsReady or not self.aapl_rsi.IsReady:
            return

        spy_close = data[self.spy].Close
        spy_sma = self.spy_sma.Current.Value

        if not self.Portfolio[self.spy].Invested:
            if (
                self.previous_spy_sma is not None
                and data[self.spy].Close > spy_sma
                and data[self.spy].Close <= self.previous_spy_sma
            ):
                quantity = int(
                    (0.40 * self.Portfolio.TotalPortfolioValue) / spy_close
                )
                if quantity > 0:
                    self.MarketOrder(self.spy, quantity, tag="Strategy A buy")
        else:
            if (
                self.previous_spy_sma is not None
                and spy_close < spy_sma
                and spy_close >= self.previous_spy_sma
            ):
                self.Liquidate(self.spy, tag="Strategy A sell")

        if not self.Portfolio[self.aapl].Invested:
            if self.aapl_red_streak >= 3 and self.Portfolio.Cash >= 20000:
                quantity = int(20000 / data[self.aapl].Close)
                if quantity > 0:
                    self.MarketOrder(self.aapl, quantity, tag="Strategy B buy")
        else:
            if self.aapl_rsi.Current.Value > 60:
                self.Liquidate(self.aapl, tag="Strategy B sell")
