            if spy_crosses_above and self.Portfolio[self.spy].Quantity == 0:
                quantity = int(
                    (0.40 * self.Portfolio.TotalPortfolioValue) / spy_bar.Close
                )
                if quantity > 0:
                    self.MarketOrder(self.spy, quantity)

            elif spy_crosses_below and self.Portfolio[self.spy].Quantity != 0:
